probe_sources.ordinary_parser:
use std::{fs, io::{self, BufRead}};
fn main() {
    for file in io::stdin().lock().lines() {
        let file = file.unwrap();
        let text = fs::read_to_string(&file).unwrap();
        match qleisli::frontend::parser::parse_module(&text) {
            Ok(_) => println!("{}\tok", file),
            Err(e) => println!("{}\terror\t{}", file, e.to_string().replace(['\t','\n','\r'], " ")),
        }
    }
}

probe_sources.sized_generic:
use std::{collections::BTreeMap,fs,path::{Path,PathBuf}};
use qleisli::frontend::sized::ParsedProgram;
fn collect(path:&Path, out:&mut BTreeMap<String,PathBuf>) {
    for item in fs::read_dir(path).unwrap() {
        let path=item.unwrap().path();
        if path.is_dir() { collect(&path,out); }
        else if path.extension().and_then(|s|s.to_str())==Some("qli") {
            assert!(out.insert(path.file_stem().unwrap().to_str().unwrap().into(),path.clone()).is_none(),"duplicate module");
        }
    }
}
fn main() {
    let mut files=BTreeMap::new();
    collect(Path::new("corpus/sized"),&mut files);
    collect(Path::new("tests/fixtures/sized_clients"),&mut files);
    let parsed=ParsedProgram::load(files.clone()).unwrap();
    println!("coherent: {} modules accepted",parsed.module_names().count());
    for name in ["amplitude","order","retiming"] {
        files.insert(name.into(),PathBuf::from(format!("tests/fixtures/measured_clients/{name}.qli")));
    }
    let parsed=ParsedProgram::load(files).unwrap();
    println!("measured: {} modules accepted",parsed.module_names().count());
    let rejection=ParsedProgram::load(BTreeMap::from([("main".into(),PathBuf::from("tests/fixtures/sized_review/unguarded_take.qli"))])).unwrap_err();
    assert_eq!(rejection.code(),"size");
    println!("unguarded_take rejected: {rejection}");
}
